func autoMigrateSchematic(ctx context.Context, old v12.Schematic) (Schematic, error) {
	nodes, err := lo.MapErr(old.Nodes, func(v v12.Node, _ int) (Node, error) {
		return MigrateNode(ctx, v)
	})
	if err != nil {
		return Schematic{}, err
	}
	edges, err := lo.MapErr(old.Edges, func(v v12.Edge, _ int) (Edge, error) {
		return MigrateEdge(ctx, v)
	})
	if err != nil {
		return Schematic{}, err
	}
	return Schematic{
		Key:     old.Key,
		Name:    old.Name,
		Nodes:   nodes,
		Edges:   edges,
		Group:   old.Group,
		Project: old.Project,
	}, nil
}

func autoMigrateSegmentedEdgeConfig(ctx context.Context, old v12.SegmentedEdgeConfig) (SegmentedEdgeConfig, error) {
	var strokeColor *color.Color
	if old.StrokeColor != nil {
		v, err := color.MigrateColor(ctx, *old.StrokeColor)
		if err != nil {
			return SegmentedEdgeConfig{}, err
		}
		strokeColor = &v
	}
	return SegmentedEdgeConfig{
		StrokeColor: strokeColor,
		Segments:    old.Segments,
	}, nil
}

func autoMigrateStaticSymbolConfig(ctx context.Context, old v12.StaticSymbolConfig) (StaticSymbolConfig, error) {
	labeledConfig, err := MigrateLabeledConfig(ctx, old.LabeledConfig)
	if err != nil {
		return StaticSymbolConfig{}, err
	}
	var strokeColor *color.Color
	if old.StrokeColor != nil {
		v, err := color.MigrateColor(ctx, *old.StrokeColor)
		if err != nil {
			return StaticSymbolConfig{}, err
		}
		strokeColor = &v
	}
	return StaticSymbolConfig{
		LabeledConfig: labeledConfig,
		ScaledConfig:  old.ScaledConfig,
		StrokeColor:   strokeColor,
	}, nil
}

func autoMigrateToggleSymbolConfig(ctx context.Context, old v12.ToggleSymbolConfig) (ToggleSymbolConfig, error) {
	toggleConfig, err := MigrateToggleConfig(ctx, old.ToggleConfig)
	if err != nil {
		return ToggleSymbolConfig{}, err
	}
	var strokeColor *color.Color
	if old.StrokeColor != nil {
		v, err := color.MigrateColor(ctx, *old.StrokeColor)
		if err != nil {
			return ToggleSymbolConfig{}, err
		}
		strokeColor = &v
	}
	return ToggleSymbolConfig{
		ToggleConfig: toggleConfig,
		StrokeColor:  strokeColor,
	}, nil
}

